package com.mzuriair.app.presentation; import androidx.annotation.NonNull; import androidx.lifecycle.ViewModel; import androidx.lifecycle.ViewModelProvider; import com.mzuriair.app.data.repository.TelemetryRepository; public class MainViewModelFactory implements ViewModelProvider.Factory {private final TelemetryRepository r; public MainViewModelFactory(TelemetryRepository r){this.r=r;} @NonNull public <T extends ViewModel>T create(@NonNull Class<T> c){return (T)new MainViewModel(r);}}
